using System;
using GrimDynasty.Rewards;
class ExperienceScalingTests {
 static int n;static void Need(bool b,string s){n++;if(!b)throw new Exception(s);}
 static int Main(){try{SystemCrtMath math;Need(SystemCrtMath.Create(TargetNumericLocale.CInvariant,out math).Status=="Known","math profile");using(math){
  uint value;Need(ExperienceScaling.Scale(75,0,null,out value).Status=="Known"&&value==75,"zero needs no native profile");Need(ExperienceScaling.Scale(75,50,null,out value).Status=="Unsupported","unknown float profile");Need(ExperienceScaling.Scale(75,50,math,out value).Status=="Known"&&value==113,"positive half rounding");Need(ExperienceScaling.Scale(75,-100,math,out value).Status=="Known"&&value==1,"negative percent keeps unconditional positive bias");Need(ExperienceScaling.Scale(100,-101,math,out value).Status=="Known"&&value==0,"modifier cancels receive body");Need(ExperienceScaling.Scale(uint.MaxValue,100,math,out value).Status=="Known"&&value==uint.MaxValue,"uint to float rounds to 2^32 and low delta wraps");Need(ExperienceScaling.Scale(0x80000000,100,math,out value).Status=="Known"&&value==0,"uint result wraps to zero");Need(ExperienceScaling.Scale(75,float.NaN,math,out value).Status=="Known"&&value==75,"UCOMISS unordered JZ skips NaN modifier");Need(ExperienceScaling.Scale(75,float.PositiveInfinity,math,out value).Status=="Unsupported","unrecovered indefinite conversion stays unsupported");
  var x=ExampleExperienceQuest.Create(75);x.Completion.World.NumericMath=math;x.Player.ExperienceGainPercent=50;Need(ExperienceRewards.Execute(x.Completion.World,new ExperienceAction{Amount=75}).Status=="Known"&&x.Player.Experience1764==213&&x.Player.Lifetime1968==313,"actual scaled XP and lifetime writes");
  x=ExampleExperienceQuest.Create(100);x.Completion.World.NumericMath=math;x.Player.ExperienceGainPercent=-101;x.Player.Experience1764=null;x.Player.Level1760=null;x.Player.Lifetime1968=null;x.Player.NextThreshold=null;x.Player.DevotionSkillVectorEmpty=null;Need(ExperienceRewards.Execute(x.Completion.World,new ExperienceAction{Amount=100}).Status=="Known"&&x.Player.Experience1764==null&&x.Player.Bio.LifeStats.ContainsKey(0),"effective zero skips counters but still processes zero Bonus Bio");
  x=ExampleExperienceQuest.Create(75);x.Completion.World.NumericMath=math;x.Player.ExperienceGainPercent=float.NaN;Need(ExperienceRewards.Execute(x.Completion.World,new ExperienceAction{Amount=75}).Status=="Known"&&x.Player.Experience1764==175,"NaN skip value flow");
  x=ExampleExperienceQuest.Create(75);x.Completion.World.NumericMath=math;x.Player.ExperienceGainPercent=float.PositiveInfinity;Need(ExperienceRewards.Execute(x.Completion.World,new ExperienceAction{Amount=75}).Status=="Unsupported"&&x.Player.Experience1764==100&&!x.Completion.World.ExperienceNameCache.Initialized,"uncovered conversion rejects atomically");
  uint before,after;math.Check(out before);ExperienceScaling.Scale(75,50,math,out value);math.Check(out after);Need(before==after,"query profile does not alter control bits");
 }Console.WriteLine("Experience scaling assertions passed: "+n);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
